  const taskTable=(rows:LawTask[])=><><div className="rk-table-wrap"><table className="rk-table"><thead><tr><th>Task / source</th><th>Owner</th><th>Due date</th><th>Priority</th><th>Status</th></tr></thead><tbody>{paginate(rows).map(t=><tr key={t.id}><td><button className="rk-record-link" onClick={()=>go("task",t.id)}><strong>{t.title}</strong><small>{t.id} · {findChecklist(data,t.profileId,t.checklistId)?.title}</small></button></td><td>{person(records,t.ownerId)}</td><td>{dateLabel(t.due)}{!t.completed&&t.due<today()&&<small className="lw-due">Overdue</small>}</td><td><B>{t.priority}</B></td><td><B>{t.completed?"Completed":"Open"}</B></td></tr>)}</tbody></table></div>{!rows.length&&<Empty>No compliance tasks match.</Empty>}{pagination(rows.length)}</>;
